// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Liveness probe
	// (GET /healthz)
	DatabaseMiddlewareHealth(ctx context.Context, request DatabaseMiddlewareHealthRequestObject) (DatabaseMiddlewareHealthResponseObject, error)
	// Cancel future bookings, anonymise past ones, disable and pseudonymise the account, delete MFA data
	// (POST /v1/ops/accountDelete)
	AccountDelete(ctx context.Context, request AccountDeleteRequestObject) (AccountDeleteResponseObject, error)
	// Read audit rows
	// (POST /v1/ops/auditList)
	AuditList(ctx context.Context, request AuditListRequestObject) (AuditListResponseObject, error)
	// Append an audit row (no appointment contents)
	// (POST /v1/ops/auditWrite)
	AuditWrite(ctx context.Context, request AuditWriteRequestObject) (AuditWriteResponseObject, error)
	// Set the doctor of a booking
	// (POST /v1/ops/bookingAssignDoctor)
	BookingAssignDoctor(ctx context.Context, request BookingAssignDoctorRequestObject) (BookingAssignDoctorResponseObject, error)
	// Cancel a future booking: status storniert, deleted_at set, reason/info cleared; owner_* filters applied in SQL
	// (POST /v1/ops/bookingCancel)
	BookingCancel(ctx context.Context, request BookingCancelRequestObject) (BookingCancelResponseObject, error)
	// Insert a booking; the exclusion constraint maps 23P01 to 409
	// (POST /v1/ops/bookingCreate)
	BookingCreate(ctx context.Context, request BookingCreateRequestObject) (BookingCreateResponseObject, error)
	// Load one booking; owner_* filters are applied in SQL, no match = 404
	// (POST /v1/ops/bookingGet)
	BookingGet(ctx context.Context, request BookingGetRequestObject) (BookingGetResponseObject, error)
	// List bookings; soft-deleted rows are never returned; owner_* filters are applied in SQL
	// (POST /v1/ops/bookingList)
	BookingList(ctx context.Context, request BookingListRequestObject) (BookingListResponseObject, error)
	// Change service, time, reason, info of a future booking
	// (POST /v1/ops/bookingUpdate)
	BookingUpdate(ctx context.Context, request BookingUpdateRequestObject) (BookingUpdateResponseObject, error)
	// Set status abgeschlossen on ended, confirmed bookings
	// (POST /v1/ops/bookingsCompletePast)
	BookingsCompletePast(ctx context.Context, request BookingsCompletePastRequestObject) (BookingsCompletePastResponseObject, error)
	// Working windows and busy intervals per doctor, no booking details
	// (POST /v1/ops/calendarGetWindows)
	CalendarGetWindows(ctx context.Context, request CalendarGetWindowsRequestObject) (CalendarGetWindowsResponseObject, error)
	// Specialties and working days of a doctor
	// (POST /v1/ops/doctorGetSchedule)
	DoctorGetSchedule(ctx context.Context, request DoctorGetScheduleRequestObject) (DoctorGetScheduleResponseObject, error)
	// List doctors with specialties
	// (POST /v1/ops/doctorList)
	DoctorList(ctx context.Context, request DoctorListRequestObject) (DoctorListResponseObject, error)
	// Replace specialties and working days; returns future bookings outside the new hours
	// (POST /v1/ops/doctorSetSchedule)
	DoctorSetSchedule(ctx context.Context, request DoctorSetScheduleRequestObject) (DoctorSetScheduleResponseObject, error)
	// Atomically mark an unused, unexpired token as used
	// (POST /v1/ops/emailTokenConsume)
	EmailTokenConsume(ctx context.Context, request EmailTokenConsumeRequestObject) (EmailTokenConsumeResponseObject, error)
	// Store the hash of a verify/reset/email_change token; older unused tokens of the same purpose are invalidated
	// (POST /v1/ops/emailTokenCreate)
	EmailTokenCreate(ctx context.Context, request EmailTokenCreateRequestObject) (EmailTokenCreateResponseObject, error)
	// Hard delete the TOTP secret and all recovery codes
	// (POST /v1/ops/mfaDelete)
	MfaDelete(ctx context.Context, request MfaDeleteRequestObject) (MfaDeleteResponseObject, error)
	// Mark the stored secret as confirmed
	// (POST /v1/ops/mfaSecretConfirm)
	MfaSecretConfirm(ctx context.Context, request MfaSecretConfirmRequestObject) (MfaSecretConfirmResponseObject, error)
	// Load the encrypted TOTP secret
	// (POST /v1/ops/mfaSecretGet)
	MfaSecretGet(ctx context.Context, request MfaSecretGetRequestObject) (MfaSecretGetResponseObject, error)
	// Store the encrypted TOTP secret of an unfinished setup; a confirmed secret is never overwritten (409 mfa_active), MFA must be removed first
	// (POST /v1/ops/mfaSecretUpsert)
	MfaSecretUpsert(ctx context.Context, request MfaSecretUpsertRequestObject) (MfaSecretUpsertResponseObject, error)
	// Atomically accept a TOTP time step once (replay protection, RFC 6238)
	// (POST /v1/ops/mfaUseStep)
	MfaUseStep(ctx context.Context, request MfaUseStepRequestObject) (MfaUseStepResponseObject, error)
	// Load one patient including the main doctor
	// (POST /v1/ops/patientGet)
	PatientGet(ctx context.Context, request PatientGetRequestObject) (PatientGetResponseObject, error)
	// Search patients by name or e-mail
	// (POST /v1/ops/patientList)
	PatientList(ctx context.Context, request PatientListRequestObject) (PatientListResponseObject, error)
	// Set or clear the main doctor
	// (POST /v1/ops/patientSetMainDoctor)
	PatientSetMainDoctor(ctx context.Context, request PatientSetMainDoctorRequestObject) (PatientSetMainDoctorResponseObject, error)
	// Hard delete expired rows of one category and write one audit row
	// (POST /v1/ops/purgeExpired)
	PurgeExpired(ctx context.Context, request PurgeExpiredRequestObject) (PurgeExpiredResponseObject, error)
	// Atomically use up one recovery code
	// (POST /v1/ops/recoveryCodeConsume)
	RecoveryCodeConsume(ctx context.Context, request RecoveryCodeConsumeRequestObject) (RecoveryCodeConsumeResponseObject, error)
	// Replace all recovery codes by new hashes
	// (POST /v1/ops/recoveryCodesReplace)
	RecoveryCodesReplace(ctx context.Context, request RecoveryCodesReplaceRequestObject) (RecoveryCodesReplaceResponseObject, error)
	// Read the retention periods A to E
	// (POST /v1/ops/retentionGet)
	RetentionGet(ctx context.Context, request RetentionGetRequestObject) (RetentionGetResponseObject, error)
	// Store the retention periods A to E; C must be >= B
	// (POST /v1/ops/retentionSet)
	RetentionSet(ctx context.Context, request RetentionSetRequestObject) (RetentionSetResponseObject, error)
	// Create a service
	// (POST /v1/ops/serviceCreate)
	ServiceCreate(ctx context.Context, request ServiceCreateRequestObject) (ServiceCreateResponseObject, error)
	// Delete a service not referenced by bookings and not is_other
	// (POST /v1/ops/serviceDelete)
	ServiceDelete(ctx context.Context, request ServiceDeleteRequestObject) (ServiceDeleteResponseObject, error)
	// Import specialties and services (JSON template)
	// (POST /v1/ops/serviceImport)
	ServiceImport(ctx context.Context, request ServiceImportRequestObject) (ServiceImportResponseObject, error)
	// List services
	// (POST /v1/ops/serviceList)
	ServiceList(ctx context.Context, request ServiceListRequestObject) (ServiceListResponseObject, error)
	// Replace a service
	// (POST /v1/ops/serviceUpdate)
	ServiceUpdate(ctx context.Context, request ServiceUpdateRequestObject) (ServiceUpdateResponseObject, error)
	// Create a specialty
	// (POST /v1/ops/specialtyCreate)
	SpecialtyCreate(ctx context.Context, request SpecialtyCreateRequestObject) (SpecialtyCreateResponseObject, error)
	// Delete a specialty not in use
	// (POST /v1/ops/specialtyDelete)
	SpecialtyDelete(ctx context.Context, request SpecialtyDeleteRequestObject) (SpecialtyDeleteResponseObject, error)
	// List specialties
	// (POST /v1/ops/specialtyList)
	SpecialtyList(ctx context.Context, request SpecialtyListRequestObject) (SpecialtyListResponseObject, error)
	// Is the token still valid (not revoked, iat >= sessions_valid_after, account active)
	// (POST /v1/ops/tokenCheck)
	TokenCheck(ctx context.Context, request TokenCheckRequestObject) (TokenCheckResponseObject, error)
	// Revoke a jti until it expires
	// (POST /v1/ops/tokenRevoke)
	TokenRevoke(ctx context.Context, request TokenRevokeRequestObject) (TokenRevokeResponseObject, error)
	// Replace the e-mail address
	// (POST /v1/ops/userChangeEmail)
	UserChangeEmail(ctx context.Context, request UserChangeEmailRequestObject) (UserChangeEmailResponseObject, error)
	// Create an account
	// (POST /v1/ops/userCreate)
	UserCreate(ctx context.Context, request UserCreateRequestObject) (UserCreateResponseObject, error)
	// Load an account including the password hash, case-insensitive e-mail
	// (POST /v1/ops/userGetByEmail)
	UserGetByEmail(ctx context.Context, request UserGetByEmailRequestObject) (UserGetByEmailResponseObject, error)
	// Load an account including the password hash
	// (POST /v1/ops/userGetById)
	UserGetById(ctx context.Context, request UserGetByIdRequestObject) (UserGetByIdResponseObject, error)
	// List accounts
	// (POST /v1/ops/userList)
	UserList(ctx context.Context, request UserListRequestObject) (UserListResponseObject, error)
	// Atomically count a failed attempt and compute the lock
	// (POST /v1/ops/userRecordLoginFailure)
	UserRecordLoginFailure(ctx context.Context, request UserRecordLoginFailureRequestObject) (UserRecordLoginFailureResponseObject, error)
	// Reset the failed-attempt counter
	// (POST /v1/ops/userRecordLoginSuccess)
	UserRecordLoginSuccess(ctx context.Context, request UserRecordLoginSuccessRequestObject) (UserRecordLoginSuccessResponseObject, error)
	// Set sessions_valid_after to now
	// (POST /v1/ops/userRevokeSessions)
	UserRevokeSessions(ctx context.Context, request UserRevokeSessionsRequestObject) (UserRevokeSessionsResponseObject, error)
	// Mark the e-mail as verified and activate a pending account
	// (POST /v1/ops/userSetEmailVerified)
	UserSetEmailVerified(ctx context.Context, request UserSetEmailVerifiedRequestObject) (UserSetEmailVerifiedResponseObject, error)
	// Store a new password hash, set sessions_valid_after, optionally must_change_password
	// (POST /v1/ops/userSetPassword)
	UserSetPassword(ctx context.Context, request UserSetPasswordRequestObject) (UserSetPasswordResponseObject, error)
	// Replace the roles; keeps doctor/patient rows in sync; sets sessions_valid_after; systemadmin must be exclusive
	// (POST /v1/ops/userSetRoles)
	UserSetRoles(ctx context.Context, request UserSetRolesRequestObject) (UserSetRolesResponseObject, error)
	// Clear the lock and the counter
	// (POST /v1/ops/userUnlock)
	UserUnlock(ctx context.Context, request UserUnlockRequestObject) (UserUnlockResponseObject, error)
	// Change name, phone, address
	// (POST /v1/ops/userUpdateProfile)
	UserUpdateProfile(ctx context.Context, request UserUpdateProfileRequestObject) (UserUpdateProfileResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// DatabaseMiddlewareHealth operation middleware
func (sh *strictHandler) DatabaseMiddlewareHealth(w http.ResponseWriter, r *http.Request) {
	var request DatabaseMiddlewareHealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.DatabaseMiddlewareHealth(ctx, request.(DatabaseMiddlewareHealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "DatabaseMiddlewareHealth")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(DatabaseMiddlewareHealthResponseObject); ok {
		if err := validResponse.VisitDatabaseMiddlewareHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

